<template>
    <section class="main-content">
        <div class=" padding-t_10">

            <div class="col-md-12 p-0">
                <div class="theme-primary">
                    <span class="p-name text-white textelipsis">
                        {{ $t("ScannedItemsStatus") }}

                    </span>
                </div>
            </div>
            <div class="row">
                <div class="col-12 mt-2">
                    <div class="mr-2 d-inline-block">
                        <span class="legends_profile colorboxsquare"></span>{{ $t("MissingProducts") }}
                    </div>
                </div>
            </div>
            <div class="listing mt-2" id="detailTable" v-if="GroupName.length != 0">
                <div v-for="(ParentItem, ParentIndex) in GroupName" :key="ParentIndex">
                    <div class="accordion custom-accr">
                        <div class="card">
                            <div class="card-header" role="tab" id="headingTwo2">
                                <a data-toggle="collapse" data-parent="#accordionEx" class="collapsed font-dark">
                                    <em class="fa fa-angle-down rotate-icon" aria-hidden="true"></em>
                                    {{ ParentItem.groupData[0].device_name }}( {{ ParentItem.groupKey }})
                                </a>
                            </div>
                            <div class="collapse show" role="tabpanel" data-parent="#accordionEx">
                                <div class="card-body py-0  px-0">
                                    <div class="table-responsive border-0">
                                        <div id="example_wrapper" class="dataTables_wrapper no-footer">
                                            <table id="example"
                                                class="table table-bordered dt-responsive nowrap mt-0 dataTable no-footer dtr-inline"
                                                style="width: 100%;" role="grid" aria-describedby="example_info">
                                                <thead class="thead-bg">
                                                    <tr role="row">
                                                        <th><span>{{ $t("Location") }}</span></th>
                                                        <th><span>{{ $t("ProductType") }}</span></th>
                                                        <th><span>{{ $t("ProductName") }}</span></th>
                                                        <th><span>{{ $t("UniqueCode") }}</span></th>
                                                        <th><span>{{ $t("Sub Location") }}</span></th>
                                                        <th><span>{{ $t("SerialNumber") }}</span></th>
                                                        <th><span>{{ $t("EPCTags") }}</span></th>
                                                        <th><span>{{ $t("IpAddress") }}</span></th>
                                                        <th><span>{{ $t("Status") }}</span></th>
                                                        <th><span>{{ $t("RFIDTagStatus") }}</span></th>
                                                        <th class="text-center"><span>{{$t("Actions")}}</span></th>
                                                    </tr>
                                                </thead>
                                                <tbody>
                                                    <!-- Tag_Status_Name == "Missing" ? "high-profile-bar" : "" -->

                                                    <tr colspan="20" class="text-center text-danger no-record"
                                                        v-if="GroupName.length == 0"> {{ $t('NoRecordfound') }} </tr>
                                                    <tr v-for="(ChildItem, ChildIndex) in ParentItem.groupData"
                                                        :key="ChildIndex"
                                                        :class="ChildItem.TAG_STATUS_NAME == 'Missing' ? 'high-profile-bar' : ''">
                                                        <td>{{ ChildItem.LOCATION_NAME }}</td>
                                                        <td>{{ ChildItem.ASSET_TYPE }}</td>
                                                        <td>{{ ChildItem.unique_name }}</td>
                                                        <td>{{ ChildItem.ITEM_CODE }}</td>
                                                        <td>{{ ChildItem.sub_location }}</td>
                                                        <td>{{ ChildItem.serial_number }}</td>
                                                        <td>{{ ChildItem.EPC_TAG }}</td>
                                                        <td>{{ ChildItem.ip_address }}({{ ChildItem.device_name }})</td>
                                                        <td>{{ ChildItem.STATUS_NAME }}</td>
                                                        <td>{{ ChildItem.TAG_STATUS_NAME === 'Missing' ? 'Missing' :
                                                            ChildItem.TAG_STATUS_NAME === 'New' ? 'New' :
                                                                ChildItem.TAG_STATUS_NAME === 'Mismatched' ? 'Mismatched' :
                                                                    'Available' }}
                                                        </td>

                                                        <td class="text-center">
                                                            <template v-if="ChildItem.TAG_STATUS_NAME === 'New'">
                                                                <a href="javascript:void(0)" title="Edit"
                                                                    style="cursor:pointer;" id="Edit"
                                                                    v-on:click="SaveTagData(ChildItem.EPC_TAG)">
                                                                    <em class="btn btn-success">Assign Device</em>
                                                                </a>
                                                            </template>
                                                            <template v-else>
                                                                <a href="javascript:void(0)" title="Edit"
                                                                    style="cursor:pointer;" id="Edit"
                                                                    v-on:click="EditRfid(ChildItem.ASSET_CATALOGUE_ID)">
                                                                    <em
                                                                        class="fa fa-pencil text-success mx-1 action-icon enable"></em>
                                                                </a>
                                                                <a href="javascript:void(0)" id="" title="Assign"
                                                                    class="d-none" v-on:click="ShowLocation(ChildItem)">
                                                                    <em
                                                                        class="fa fa-user pr-2 text-primary action-icon mx-1"></em>
                                                                </a>
                                                                <a href="javascript:void(0);" title="Location">
                                                                    <em
                                                                        class="fa fa-map-marker mx-1 text-warning action-icon"></em>
                                                                </a>
                                                            </template>
                                                            <template>
                                                                <template
                                                                    v-if="ChildItem.ButtonType === 'Checkout' && ChildItem.TAG_STATUS_NAME != 'Mismatched' && ChildItem.TAG_STATUS_NAME != 'Missing'">
                                                                    <a href="javascript:void(0)" title="Check Out"
                                                                        id="btnCheckOut"
                                                                        v-on:click="CheckOut(ChildItem.related_info_id)">
                                                                        <em
                                                                            class="fa fa-sign-out text-info action-icon mx-1"></em>
                                                                    </a>
                                                                </template>
                                                                <template
                                                                    v-else-if="ChildItem.ButtonType === 'Checkin' && ChildItem.TAG_STATUS_NAME != 'Mismatched' && ChildItem.TAG_STATUS_NAME != 'Missing'">
                                                                    <a href="javascript:void(0)" title="Check In"
                                                                        id="btnCheckIn" v-on:click="CheckIn()"
                                                                        data-placement="left">
                                                                        <em
                                                                            class="fa fa-sign-in text-info action-icon mx-1"></em>
                                                                    </a>
                                                                </template>
                                                            </template>
                                                        </td>
                                                    </tr>
                                                </tbody>
                                            </table>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="listing mt-2" id="detailTable" v-if="GroupName.length == 0">

                <div class="accordion custom-accr">
                    <div class="card">
                        <div class="collapse show" role="tabpanel" data-parent="#accordionEx">
                            <div class="card-body py-0 px-0">
                                <div class="table-responsive border-0">
                                    <div id="example_wrapper" class="dataTables_wrapper no-footer">
                                        <table id="example"
                                            class="table table-bordered dt-responsive nowrap mt-0 dataTable no-footer dtr-inline"
                                            style="width: 100%;" role="grid" aria-describedby="example_info">
                                            <thead class="thead-bg">
                                                <tr role="row">
                                                    <th><span>Location</span></th>
                                                    <th><span>Product Type</span></th>
                                                    <th><span>Product Name</span></th>
                                                    <th><span>Unique Code</span></th>
                                                    <th><span>Sub Location</span></th>
                                                    <th><span>Serial Number</span></th>
                                                    <th><span>EPC Tags</span></th>
                                                    <th><span>IP Address</span></th>
                                                    <th><span>Status</span></th>
                                                    <th class="text-center"><span>Actions</span></th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                <tr v-if="GroupName.length == 0">
                                                    <td class="text-center text-danger no-record" colspan="20"> {{
                                                        $t('NoRecordfound') }} </td>
                                                </tr>

                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

            </div>

        </div>

    </section>
</template>

<script>
import DataService from '../../service/DataService'
export default {
    data() {
        return {
            isLoading: false,
            Scanneditemsdata: [],
            searchdata: '',
            locationId: '',
            pageSize: 100,
            pageNum: 1,
            sortBy: '',
            sortExp: '',
            ePC_TAG: '',
            GroupName: []
        }
    },
    created() {

        this.fetchData();
    },
    methods: {
        fetchData() {

            var vueObj = this;
            var params = `search=${vueObj.searchdata}&locationId=${vueObj.locationId}&pageSize=${vueObj.pageSize}&pageNum=${vueObj.pageNum}&sortBy=${vueObj.sortBy}&sortExp=${vueObj.sortExp}&ePC_TAG=${vueObj.ePC_TAG}`;
            DataService.GetScanneditemsData(params).then(response => {
                if (response.data != '' && response.data != null) {

                    vueObj.Scanneditemsdata = response.data
                    vueObj.GroupName = [];
                    var gruopBy = "";
                    $.each(vueObj.Scanneditemsdata, $.proxy(function (index, item) {
                        gruopBy = item.ip_address;
                        var chkGroup = $.grep(vueObj.GroupName, function (element, index) {
                            return element.groupKey == gruopBy;
                        });
                        if (chkGroup.length == 0) {
                            var returnedData = $.grep(vueObj.Scanneditemsdata, function (element, index) {
                                return element.ip_address == gruopBy;
                            });
                            if (returnedData.length > 0) {
                                var objGroup = {
                                    groupKey: gruopBy,
                                    groupData: returnedData,
                                };
                                vueObj.GroupName.push(objGroup);
                            }
                        }
                    }, this));
                    console.log('dsfgfdsg', vueObj.GroupName)
                }
            }).catch(err => {
                console.log(err)
            })
        },
        EditRfid: function (AssetCatalogueID) {
            if (AssetCatalogueID > 0) {
                this.$router.push({
                    path: '/AssetCatalog/Update/' + AssetCatalogueID
                })

                // this.$router.push({name: 'UpdateProducts', params: { id: AssetCatalogueID }});
            }
        },
        SaveTagData: function (ePC_TAG) {
            if (ePC_TAG.length > 0) {
                var param = `ePC_TAG=${ePC_TAG}`;
                DataService.SaveNewRFIDTag(param).then(response => {
                    if (response.data) {
                        vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('New_Requisition')]), "Success", true, vm.$t('Alert'));
                        vm.FetchData();
                    }
                    else {
                        vm.ShowAlert(vm.$t('DeletedError', [vm.$t('New_Requisition')]), "failure", true, vm.$t('Alert'));
                    }
                });
            }

        },
        CheckOut: function (RelatedInfoId) {
            this.$router.push({
                path: '/AssetAssignment/Add/:reqForm=rfidtagstatus'// + AssetCatalogueID
            })
        },
        CheckIn: function (AssetCatalogueID) {
            this.$router.push({
                path: '/Asset/ReturnItems'
            })
        },
        ShowLocation: function (Item) {
            debugger;

        },
    }
}
</script>
